package com.foodordering.payment;
import jakarta.validation.Valid; import java.math.BigDecimal; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.*; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/payments") public class PaymentController {private final PaymentRepository r;@Value("${payment.max-amount}") BigDecimal max;PaymentController(PaymentRepository r){this.r=r;}private PaymentResponse dto(Payment p){return new PaymentResponse(p.paymentId,p.orderId,p.amount,p.paymentStatus.name(),p.paymentDate);}@PostMapping @ResponseStatus(HttpStatus.CREATED) @Transactional PaymentResponse pay(@Valid @RequestBody PaymentRequest x){var prior=r.findByOrderId(x.orderId());if(prior.filter(p->p.paymentStatus==PaymentStatus.SUCCESS).isPresent())return dto(prior.get());if(prior.isPresent()){r.delete(prior.get());r.flush();}boolean fail=Boolean.TRUE.equals(x.simulateFailure())||x.amount().signum()<=0||x.amount().compareTo(max)>0;return dto(r.save(Payment.of(x.orderId(),x.amount(),x.paymentMethod()==null?"CARD":x.paymentMethod(),fail?PaymentStatus.FAILED:PaymentStatus.SUCCESS)));}@GetMapping("/order/{orderId}") PaymentResponse get(@PathVariable Long orderId){return dto(r.findByOrderId(orderId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Payment not found")));}}
